import{_ as p,C as n,o as e,c as h,j as a,a as i,b as d,w as t,E as o,a3 as r,a2 as k}from"./chunks/framework.BQq6mqvm.js";const y=JSON.parse('{"title":"前后端分离部署","description":"","frontmatter":{},"headers":[],"relativePath":"guide/deploy-split.md","filePath":"guide/deploy-split.md","lastUpdated":1790385461000}'),c={name:"guide/deploy-split.md"};function F(g,s,C,u,B,b){const l=n("Mermaid");return e(),h("div",null,[s[1]||(s[1]=a("h1",{id:"前后端分离部署",tabindex:"-1"},[i("前后端分离部署 "),a("a",{class:"header-anchor",href:"#前后端分离部署","aria-label":'Permalink to "前后端分离部署"'},"​")],-1)),s[2]||(s[2]=a("p",null,[i("如果希望员工在"),a("strong",null,"外网也能打开页面"),i("，可以把网页端放到公网，服务端留在内网。")],-1)),(e(),d(r,null,{default:t(()=>[o(l,{id:"mermaid-6",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20%E5%85%AC%E7%BD%91%0A%20%20%20%20%20%20%20%20W%5B%E7%BD%91%E9%A1%B5%E7%AB%AF%3Cbr%2F%3E%E9%9D%99%E6%80%81%E7%AB%99%E7%82%B9%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20%E5%85%AC%E5%8F%B8%E5%86%85%E7%BD%91%0A%20%20%20%20%20%20%20%20A%5B%E6%9C%8D%E5%8A%A1%E7%AB%AF%E6%8E%A5%E5%8F%A3%5D%0A%20%20%20%20%20%20%20%20D%5B(%E6%95%B0%E6%8D%AE%E4%B8%8E%E6%96%87%E4%BB%B6)%5D%0A%20%20%20%20end%0A%20%20%20%20W%20--%20%22%E8%B7%A8%E5%9F%9F%E8%AF%B7%E6%B1%82%22%20--%3E%20A%0A%20%20%20%20A%20--%3E%20D%0A"})]),fallback:t(()=>[...s[0]||(s[0]=[i(" Loading... ",-1)])]),_:1})),s[3]||(s[3]=k(`<p>这样做的好处是：员工在家里打开页面能正常加载，但只有连上公司网络（或 VPN）才能看到文件内容。不在公司网络时，页面会明确提示「无法在此网络下使用，请更换网络再试！」，而不是让人误以为是密码错误。</p><h2 id="第一步-内网部署服务端" tabindex="-1">第一步：内网部署服务端 <a class="header-anchor" href="#第一步-内网部署服务端" aria-label="Permalink to &quot;第一步：内网部署服务端&quot;">​</a></h2><p>按<a href="./deploy">部署</a>走完流程，区别只有一处：<strong>把 <code>docker-compose.yml</code> 里的 <code>web</code> 一段删掉</strong>，只保留 <code>api</code>。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>数据库同样用 1Panel 应用商店安装，不需要单独部署。</p><div class="tip custom-block"><p class="custom-block-title">只跑服务端时，CORS 要填公网网页端的地址</p><p><code>.env</code> 里的 <code>LANDRIVE_CORS_ALLOW</code> 填<strong>用户在浏览器里打开的网页地址</strong>（即下面第二步里公网站点的域名），而不是内网地址。</p></div><h2 id="第二步-公网部署网页端" tabindex="-1">第二步：公网部署网页端 <a class="header-anchor" href="#第二步-公网部署网页端" aria-label="Permalink to &quot;第二步：公网部署网页端&quot;">​</a></h2><p>网页端镜像支持两种连后端的方式，<strong>同一个镜像靠环境变量切换</strong>。</p><h3 id="方式一-跨域直连-推荐用于分离部署" tabindex="-1">方式一：跨域直连（推荐用于分离部署） <a class="header-anchor" href="#方式一-跨域直连-推荐用于分离部署" aria-label="Permalink to &quot;方式一：跨域直连（推荐用于分离部署）&quot;">​</a></h3><p>浏览器直接请求内网接口的对外地址，需要后端配置 <code>LANDRIVE_CORS_ALLOW</code>。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lan-drive-web</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 80:80</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> LANDRIVE_API_BASE_URL=&#39;https://api.example.com/api&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  ghcr.io/sakana-1314/lan-drive:web</span></span></code></pre></div><p>其中 <code>LANDRIVE_API_BASE_URL</code> 填<strong>内网服务端的对外地址</strong>（要带 <code>/api</code>）。</p><h3 id="方式二-网页端反代" tabindex="-1">方式二：网页端反代 <a class="header-anchor" href="#方式二-网页端反代" aria-label="Permalink to &quot;方式二：网页端反代&quot;">​</a></h3><p>网页端容器自己把 <code>/api</code> 转发到你指定的地址。适合网页端与某台可达服务器之间网络通畅的情形：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lan-drive-web</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 80:80</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> LANDRIVE_API_PROXY=api.example.com:8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  ghcr.io/sakana-1314/lan-drive:web</span></span></code></pre></div><p>两者选一个即可：</p><ul><li>方式一：浏览器直连接口，<strong>后端必须配 CORS</strong>；</li><li>方式二：浏览器只访问网页端域名，<strong>不跨域、不用配 CORS</strong>。</li></ul><div class="tip custom-block"><p class="custom-block-title">怎么选</p><p>内网接口有独立的对外域名（如 <code>api.example.com</code>）→ 用方式一，链路最短。</p><p>只想暴露一个域名、或不想维护 CORS 白名单 → 用方式二。</p></div><h2 id="第三步-让两边能通" tabindex="-1">第三步：让两边能通 <a class="header-anchor" href="#第三步-让两边能通" aria-label="Permalink to &quot;第三步：让两边能通&quot;">​</a></h2><p>需要满足两个条件：</p><ol><li><strong>公网能访问到内网接口</strong> —— 通常通过 VPN、内网穿透或网关转发实现。</li><li><strong>服务端放行网页端地址</strong> —— 即 <code>LANDRIVE_CORS_ALLOW</code> 必须等于用户浏览器里打开的网页地址。</li></ol><p>验证跨域是否配置正确（在内网机器上执行）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> OPTIONS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8080/api/auth/login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Origin: https://files.example.com&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Access-Control-Request-Method: POST&#39;</span></span></code></pre></div><p>响应里应该出现：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Access-Control-Allow-Origin: https://files.example.com</span></span></code></pre></div><p>如果没有这一行，说明地址没配对，用户会一直看到「无法在此网络下使用」。</p><div class="tip custom-block"><p class="custom-block-title">常见疑问：为什么在内网能打开页面，却提示换网络？</p><p>因为网页端在公网、接口在内网。在内网时两者都通；一旦离开内网，页面还能打开（缓存在浏览器里），但接口请求发不出去，于是提示更换网络。</p></div><h2 id="改为同机部署" tabindex="-1">改为同机部署 <a class="header-anchor" href="#改为同机部署" aria-label="Permalink to &quot;改为同机部署&quot;">​</a></h2><p>如果不需要外网访问，按<a href="./deploy">部署</a>把两个容器放同一台机器上更省事。</p>`,29))])}const m=p(c,[["render",F]]);export{y as __pageData,m as default};
